data = json.loads(maze_json)
open_mask = data['openMask']
start_x, start_y = data['start']
end_x, end_y = data['end']

queue = deque([(start_x, start_y, "")])
visited = set()
visited.add((start_x, start_y))

directions = [
    (0, -1, 'U', 1),
    (1,  0, 'R', 2),
    (0,  1, 'D', 4),
    (-1, 0, 'L', 8)
]

while queue:
    x, y, path = queue.popleft()
    if x == end_x and y == end_y:
        print("\n--- COPY THIS EXACT STRING ---")
        print(path)
        print("-------------------------------")
        break
    mask = open_mask[y][x]
    for dx, dy, move, bit in directions:
        if mask & bit:
            nx, ny = x + dx, y + dy
            if 0 <= ny < len(open_mask) and 0 <= nx < len(open_mask[0]):
                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, path + move))